function kilogramsByBed(harvestRows) {
  const totals = {}
  for (let i = 1; i < harvestRows.length; i++) {
    const bedId = harvestRows[i][1]
    if (totals[bedId] === undefined) {
      totals[bedId] = 0
    }
    totals[bedId] += harvestRows[i][3]
  }
  return totals
}
